from collections import deque
from datetime import datetime, timedelta, time

from AlgorithmImports import *


class FiveMinuteBarBuilder:
    """Builds regular-session five-minute bars without filling missing minutes."""

    def __init__(self, callback):
        self.callback = callback
        self.bucket_start = None
        self.minutes = []
        self.bars = []

    def update(self, bar):
        local_time = bar.EndTime.astimezone(TimeZones.NewYork)
        bar_start = local_time.replace(second=0, microsecond=0) - timedelta(minutes=1)

        # Only regular-session SPY bars are used.
        if bar_start.time() < time(9, 30) or bar_start.time() >= time(16, 0):
            return

        bucket_minute = (bar_start.minute // 5) * 5
        bucket_start = bar_start.replace(minute=bucket_minute)

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._flush()
            self.bucket_start = bucket_start
            self.minutes = []

        self.minutes.append((bar_start, float(bar.Close)))

    def _flush(self):
        if self.bucket_start is None:
            return

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        actual = [x[0] for x in self.minutes]

        # Do not emit partial or gapped bars.
        if actual == expected:
            close = self.minutes[-1][1]
            end_time = self.bucket_start + timedelta(minutes=5)
            self.callback(end_time, close)

        self.minutes = []

    def reset(self):
        self._flush()
        self.bucket_start = None
        self.minutes = []


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            True,
            1,
            True
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bar_builder = FiveMinuteBarBuilder(self._on_five_minute_bar)

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_date = None
        self.expiration_handled_date = None
        self.exercise_handled_date = None

    def OnData(self, slice: Slice):
        self.current_slice = slice
        now = self.Time
        today = now.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(today)

        if self.held_option is not None:
            self._evaluate_option_exit(slice)

        if self.entry_ticket is None and self.held_option is None:
            bar = slice.Bars.get(self.spy.Symbol)
            if bar is not None:
                self.bar_builder.update(bar)

    def _on_five_minute_bar(self, end_time, close):
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if bullish_cross and eligible_time:
            self._try_enter()

    def _try_enter(self):
        if self.current_slice is None:
            return

        if self.entry_ticket is not None or self.held_option is not None:
            return

        today = self.Time.date()
        minimum_expiration = today + timedelta(days=7)
        spy_price = float(self.Securities[self.spy.Symbol].Price)

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chain = None
        for candidate_chain in self.current_slice.OptionChains.Values:
            if candidate_chain.Symbol == self.spy_option.Symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Skipped selection: no current SPY option chain.")
            return

        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiration
            and contract.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)

        contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            contracts,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.held_option = selected.Symbol
        self.entry_price = None
        self.time_stop_date = self._previous_trading_day(nearest_expiry)

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ):
            return

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        f"Entry filled: {order_event.Symbol}, "
                        f"price={self.entry_price:.4f}"
                    )
                    self.entry_ticket = None
                return

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol}, "
                        f"price={order_event.FillPrice:.4f}"
                    )
                    self.exit_ticket = None
                    self.held_option = None
                    self.entry_price = None
                    self.time_stop_date = None

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            return

        if self.Portfolio[self.held_option].Quantity <= 0:
            return

        contract = None
        for chain in slice.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _handle_expiration_processing(self, today):
        if self.held_option is None:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()

        if expiry <= today:
            if self.expiration_handled_date != today:
                self.expiration_handled_date = today
                self._liquidate_option("expiration processing")
            return

        if (
            self.time_stop_date == today
            and self.Time.time() >= time(15, 45)
        ):
            self._liquidate_option("pre-expiration time stop")

    def _liquidate_option(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)
            self.exit_ticket = None

        self.Debug(f"Option exit submitted: {reason}")
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity != 0:
            today = self.Time.date()

            if self.exercise_handled_date != today:
                self.exercise_handled_date = today
                self.Debug(
                    f"Unexpected SPY exercise/assignment position detected: "
                    f"quantity={quantity}"
                )

            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            candidate
        ):
            candidate -= timedelta(days=1)

        return candidate
