            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)
            self.exit_ticket = None

        self.Debug(f"Option exit submitted: {reason}")
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity != 0:
            today = self.Time.date()

            if self.exercise_handled_date != today:
                self.exercise_handled_date = today
                self.Debug(
                    f"Unexpected SPY exercise/assignment position detected: "
                    f"quantity={quantity}"
                )

            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            candidate
        ):
            candidate -= timedelta(days=1)

        return candidate

