                str(candidate.Symbol)
            ) < (
                selected.Expiry.date(),
                selected.Strike,
                str(selected.Symbol)
            ):
                selected = candidate

        if selected is None:
            self.Debug(
                f"{self.Time}: skipped option selection; no qualifying call"
            )
            return

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"{self.Time}: submitted entry for {selected.Symbol}")

