            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .CallsOnly()
                .Strikes(-100, 100)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = RollingWindow[float](5)
        self.slow = RollingWindow[float](20)

        self.bucket_end = None
        self.bucket_bars = {}
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None
        self.expiration_date = None
        self.previous_expiration_trading_day = None
        self.no_replacement_today = None

    def OnData(self, slice: Slice):
        self._handle_equity_assignment()

        if self.held_contract is not None:
            self._evaluate_exit(slice)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._update_five_minute_bar(bar, slice)

    def _update_five_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime
        session_start = time(9, 30)
        session_end = time(16, 0)

        if end.time() <= session_start or end.time() > session_end:
            return

        minute_index = (end.hour * 60 + end.minute) - (9 * 60 + 31)
        if minute_index < 0:
            return

        bucket_index = minute_index // 5
        bucket_end = end.replace(
            hour=9,
            minute=31,
            second=0,
            microsecond=0
        ) + timedelta(minutes=(bucket_index + 1) * 5)

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._finalize_bucket(slice)

        if self.bucket_end is None:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end] = bar

        if end == self.bucket_end:
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice: Slice):
        if self.bucket_end is None:
            return

        bars = list(self.bucket_bars.values())
        expected_minutes = {
            self.bucket_end - timedelta(minutes=i)
            for i in range(5)
        }

        actual_minutes = {bar.EndTime for bar in bars}

        if len(bars) == 5 and actual_minutes == expected_minutes:
            close = bars[-1].Close

            self.fast.Add(close)
            self.slow.Add(close)

            if self.fast.IsReady and self.slow.IsReady:
                current_fast = sum(self.fast[i] for i in range(5)) / 5.0
                current_slow = sum(self.slow[i] for i in range(20)) / 20.0

                bullish_cross = (
                    self.previous_fast is not None
                    and self.previous_slow is not None
                    and self.previous_fast <= self.previous_slow
                    and current_fast > current_slow
                )

                if bullish_cross:
                    bar_end_time = self.bucket_end.time()
                    if time(9, 45) <= bar_end_time <= time(14, 30):
                        self._try_entry(slice, close)

                self.previous_fast = current_fast
                self.previous_slow = current_slow

        self.bucket_end = None
        self.bucket_bars = {}

    def _try_entry(self, slice: Slice, spy_price: float):
        if self.no_replacement_today == self.Time.date():
            return

        if self.held_contract is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chains = slice.OptionChains
        selected = None
        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        for chain in chains:
            candidates = [
                contract for contract in chain
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() >= minimum_expiration
                and contract.Strike >= spy_price * 1.01
            ]

            if not candidates:
                continue

            nearest_expiration = min(
                contract.Expiry.date() for contract in candidates
            )

            candidates = [
                contract for contract in candidates
                if contract.Expiry.date() == nearest_expiration
            ]

            candidate = min(
                candidates,
                key=lambda contract: (
                    contract.Strike,
                    str(contract.Symbol)
                )
            )

            if selected is None or (
                candidate.Expiry.date(),
                candidate.Strike,
                str(candidate.Symbol)
            ) < (
                selected.Expiry.date(),
                selected.Strike,
                str(selected.Symbol)
            ):
                selected = candidate

        if selected is None:
            self.Debug(
                f"{self.Time}: skipped option selection; no qualifying call"
            )
            return

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"{self.Time}: submitted entry for {selected.Symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)

        if order_event.IsAssignment:
            self.Debug(
                f"{self.Time}: unexpected exercise/assignment: "
                f"{order_event.Symbol}"
            )
            if self.Portfolio[self.spy].Invested:
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity
                )
