            self.entry_price = order_event.FillPrice
            self.expiration_date = self.Securities[
                self.held_contract
            ].Symbol.ID.Date.date()

            self.previous_expiration_trading_day = (
                self.Securities[self.spy]
                .Exchange.Hours.GetPreviousTradingDay(
