from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            True,
            1.0,
            False
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA, True)
        option.SetFilter(lambda universe: universe
                         .IncludeWeeklys()
                         .Strikes(-100, 100)
                         .Expiration(timedelta(days=0), timedelta(days=730)))
        self.option_symbol = option.Symbol

        self.fast_values = RollingWindow[float](5)
        self.slow_values = RollingWindow[float](20)

        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_start = None
        self.current_bucket_prices = {}
        self.latest_option_chain = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_stop_submitted = False
        self.block_entries_today = False

    def OnData(self, slice: Slice):
        self.latest_option_chain = {}

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                self.latest_option_chain[contract.Symbol] = contract

        # Immediately liquidate unexpected SPY equity positions.
        spy_holdings = self.Portfolio[self.spy].Quantity
        if spy_holdings != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: {spy_holdings}; liquidating."
            )
            self.MarketOrder(self.spy, -spy_holdings)
            self.block_entries_today = True

        self._process_expiration()
        self._process_option_exit(slice)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        local_time = self.Time
        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return

        minute = local_time.replace(second=0, microsecond=0)
        bucket_minute = ((minute.minute - 30) // 5) * 5 + 30
        bucket_start = minute.replace(minute=bucket_minute)

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start

        if bucket_start != self.current_bucket_start:
            self._complete_five_minute_bar()
            self.current_bucket_start = bucket_start
            self.current_bucket_prices = {}

        self.current_bucket_prices[minute] = float(bar.Close)

    def _complete_five_minute_bar(self):
        if self.current_bucket_start is None:
            return

        # Require all five minute observations. Missing bars are discarded.
        expected = {
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        }

        if set(self.current_bucket_prices.keys()) != expected:
            self.current_bucket_prices = {}
            return

        close = self.current_bucket_prices[
            self.current_bucket_start + timedelta(minutes=4)
        ]

        self.fast_values.Add(close)
        self.slow_values.Add(close)

        if not self.fast_values.IsReady:
            self.current_bucket_prices = {}
            return

        current_fast = sum(self.fast_values[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_values[i] for i in range(20)) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        bar_end = self.current_bucket_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if (
            crossover
            and eligible_time
            and not self.block_entries_today
            and self.entry_ticket is None
            and not self._option_is_held()
        ):
            self._enter_call()

        self.previous_fast = current_fast
        self.previous_slow = current_slow
        self.current_bucket_prices = {}

    def _enter_call(self):
        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        candidates = [
            contract for contract in self.latest_option_chain.values()
            if contract.Symbol.ID.OptionRight == OptionRight.Call
            and contract.Symbol.ID.Date.date() >= minimum_expiry
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible contracts.")
            return

        nearest_expiry = min(
            contract.Symbol.ID.Date.date() for contract in candidates
        )

        same_expiry = [
            contract for contract in candidates
            if contract.Symbol.ID.Date.date() == nearest_expiry
        ]

        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = spy_price * 1.01

        strikes = [
            contract for contract in same_expiry
            if float(contract.Strike) >= minimum_strike
        ]

        if not strikes:
            self.Debug("Skipped call selection: no strike at least 1% OTM.")
            return

        selected = min(
            strikes,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

        self.Debug(
            f"Call entry submitted: {self.entry_symbol}, "
            f"expiry={nearest_expiry}, strike={selected.Strike}"
        )

    def _process_option_exit(self, slice: Slice):
        if not self._option_is_held() or self.entry_price is None:
            return

        symbol = self.entry_symbol
        contract = self.latest_option_chain.get(symbol)

        if contract is not None:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_price * 1.50:
                    self._liquidate_option("50% profit target")

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

    def _process_expiration(self):
        if not self._option_is_held() or self.entry_symbol is None:
            return

        expiry = self.entry_symbol.ID.Date.date()

        if self.Time.date() >= expiry:
            self.block_entries_today = True
            self._liquidate_option("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry)

        if (
            self.Time.date() == previous_trading_day
