    def OnData(self, slice: Slice):
        self.latest_option_chain = {}

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                self.latest_option_chain[contract.Symbol] = contract

        # Immediately liquidate unexpected SPY equity positions.
        spy_holdings = self.Portfolio[self.spy].Quantity
        if spy_holdings != 0:
            self.Debug(
                f"Unexpected SPY equity position detected: {spy_holdings}; liquidating."
            )
            self.MarketOrder(self.spy, -spy_holdings)
            self.block_entries_today = True

        self._process_expiration()
        self._process_option_exit(slice)

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        local_time = self.Time
        if local_time.time() < time(9, 30) or local_time.time() >= time(16, 0):
            return

        minute = local_time.replace(second=0, microsecond=0)
        bucket_minute = ((minute.minute - 30) // 5) * 5 + 30
        bucket_start = minute.replace(minute=bucket_minute)

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start

        if bucket_start != self.current_bucket_start:
            self._complete_five_minute_bar()
            self.current_bucket_start = bucket_start
            self.current_bucket_prices = {}

        self.current_bucket_prices[minute] = float(bar.Close)

    def _complete_five_minute_bar(self):
        if self.current_bucket_start is None:
            return

        # Require all five minute observations. Missing bars are discarded.
        expected = {
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        }

        if set(self.current_bucket_prices.keys()) != expected:
            self.current_bucket_prices = {}
            return

        close = self.current_bucket_prices[
            self.current_bucket_start + timedelta(minutes=4)
        ]

        self.fast_values.Add(close)
        self.slow_values.Add(close)

        if not self.fast_values.IsReady:
            self.current_bucket_prices = {}
            return

        current_fast = sum(self.fast_values[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_values[i] for i in range(20)) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        bar_end = self.current_bucket_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

